            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.title != rhs.title {
            return false
        }
        if lhs.description != rhs.description {
            return false
        }
        if lhs.image != rhs.image {
            return false
        }
        if lhs.articleAddresses != rhs.articleAddresses {
            return false
        }
        if lhs.noteIds != rhs.noteIds {
            return false
        }
        if lhs.createdAt != rhs.createdAt {
