/**
 * A kind:11 discussion can reference an artifact the way a share does —
 * the tag shape matches `ArtifactPreview`'s reference fields exactly, so we
 * reuse the same vocabulary here.
 */
public struct DiscussionAttachment {
    /**
     * "a" | "e" | "i" | "r" (r-only means bare URL, no catalog reference).
     */
    public var referenceTagName: String
    public var referenceTagValue: String
    public var referenceKind: String
    public var url: String
    public var title: String
    public var author: String
    public var image: String
    public var summary: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * "a" | "e" | "i" | "r" (r-only means bare URL, no catalog reference).
         */referenceTagName: String, referenceTagValue: String, referenceKind: String, url: String, title: String, author: String, image: String, summary: String) {
        self.referenceTagName = referenceTagName
        self.referenceTagValue = referenceTagValue
        self.referenceKind = referenceKind
        self.url = url
        self.title = title
        self.author = author
        self.image = image
        self.summary = summary
    }
}

