    public static func ==(lhs: DiscussionAttachment, rhs: DiscussionAttachment) -> Bool {
        if lhs.referenceTagName != rhs.referenceTagName {
            return false
        }
        if lhs.referenceTagValue != rhs.referenceTagValue {
            return false
        }
        if lhs.referenceKind != rhs.referenceKind {
            return false
        }
        if lhs.url != rhs.url {
            return false
        }
        if lhs.title != rhs.title {
            return false
        }
        if lhs.author != rhs.author {
            return false
        }
        if lhs.image != rhs.image {
            return false
        }
        if lhs.summary != rhs.summary {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(referenceTagName)
        hasher.combine(referenceTagValue)
        hasher.combine(referenceKind)
        hasher.combine(url)
        hasher.combine(title)
        hasher.combine(author)
        hasher.combine(image)
        hasher.combine(summary)
    }
}



