/**
 * NIP-01 kind:0 profile metadata. Mirrors the fields the web profile page
 * reads from `NDKUser.profile`. Empty strings for missing fields so Swift
 * call sites don't deal with `Option` everywhere.
 */
public struct ProfileMetadata {
    public var pubkey: String
    public var name: String
    public var displayName: String
    public var about: String
    public var picture: String
    public var banner: String
    public var nip05: String
    public var website: String
    public var lud16: String
    /**
     * created_at of the kind:0 event this came from (seconds since epoch).
     */
    public var createdAt: UInt64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(pubkey: String, name: String, displayName: String, about: String, picture: String, banner: String, nip05: String, website: String, lud16: String,
        /**
         * created_at of the kind:0 event this came from (seconds since epoch).
         */createdAt: UInt64?) {
        self.pubkey = pubkey
        self.name = name
        self.displayName = displayName
        self.about = about
        self.picture = picture
        self.banner = banner
        self.nip05 = nip05
        self.website = website
        self.lud16 = lud16
        self.createdAt = createdAt
    }
}

